def compute_by_distance(inputs, sep_row):
    """Sort sep_below by |row - sep_row| descending (furthest first)"""
    result = set()

    sep_below = [(r, c) for r, c in inputs if sep_row >= r]

    if not sep_below:
        return sorted(result)

    # Sort by distance descending (furthest first)
    sep_below_sorted = sorted(sep_below, key=lambda x: abs(x[0] - sep_row), reverse=True)

    for i in range(len(sep_below_sorted)):
        r0, c0 = sep_below_sorted[i]
        is_furthest = (i == 0)

        # L1=3
        sep_above = sep_row < r0

        if sep_above:
            for dc in [2, -2]:
                r1, c1 = sep_row, c0 + dc
                if 0 <= r1 < 12 and 0 <= c1 < 8:
                    result.add((r1, c1))
        else:
            # sep BELOW: furthest gets L1=3
            if is_furthest:
                r1, c1 = r0 - 2, c0 - 1
                if 0 <= r1 < 12 and 0 <= c1 < 8:
                    result.add((r1, c1))

        # L1=1: furthest gets UP, rest get DOWN
        if is_furthest:
            for dr, dc in [(-1, 0), (0, 1), (1, 0)]:  # UP, RIGHT, DOWN
                r1, c1 = r0 + dr, c0 + dc
                if 0 <= r1 < 12 and 0 <= c1 < 8:
                    result.add((r1, c1))
        else:
            for dr, dc in [(0, -1), (0, 1), (1, 0)]:  # LEFT, RIGHT, DOWN
                r1, c1 = r0 + dr, c0 + dc
                if 0 <= r1 < 12 and 0 <= c1 < 8:
                    result.add((r1, c1))

    return sorted(result)

